def _interpolate_all(
    sections: dict[str, dict[str, str]]
) -> dict[str, dict[str, str]]:
    """Interpolate every value, returning a new section mapping."""
    cache: dict[tuple[str, str], str] = {}
    stack: list[tuple[str, str]] = []

    def resolve(section: str, key: str) -> str:
        ident = (section, key)
        if ident in cache:
            return cache[ident]
        if ident in stack:
            start = stack.index(ident)
            cycle = stack[start:] + [ident]
            chain = " -> ".join(f"{sec}:{name}" for sec, name in cycle)
            raise InterpolationError(f"interpolation cycle: {chain}")
        stack.append(ident)
        try:
            value = interpolate(sections[section][key], section)
        finally:
            stack.pop()
        cache[ident] = value
        return value

    def lookup(section: str, reference: str) -> str:
        if ":" in reference:
            ref_section, ref_key = reference.split(":", 1)
            ref_section = ref_section.strip()
            ref_key = ref_key.strip().lower()
        else:
            ref_section = section
            ref_key = reference.strip().lower()
        if ref_section not in sections:
            raise InterpolationError(
                f"reference to missing section {ref_section!r}"
            )
        if ref_key not in sections[ref_section]:
            raise InterpolationError(
                f"reference to missing key {ref_key!r} "
                f"in section {ref_section!r}"
            )
        return resolve(ref_section, ref_key)

    def interpolate(text: str, section: str) -> str:
        pieces: list[str] = []
        index = 0
        length = len(text)
        while index < length:
            if text[index] != "$":
                pieces.append(text[index])
                index += 1
                continue
            if text.startswith("$$", index):
                pieces.append("$")
                index += 2
                continue
            if text.startswith("${", index):
                end = text.find("}", index + 2)
                if end != -1:
                    reference = text[index + 2:end]
                    if reference.strip():
                        pieces.append(lookup(section, reference))
                        index = end + 1
                        continue
            pieces.append("$")
            index += 1
        return "".join(pieces)

    result: dict[str, dict[str, str]] = {}
    for section, values in sections.items():
        result[section] = {key: resolve(section, key) for key in values}
    return result


def parse(text: str) -> dict[str, dict[str, str]]:
    """Parse INI text."""
    sections: dict[str, dict[str, str]] = {}
    current_section: str | None = None
    continuation: tuple[str, str] | None = None

    for lineno, line in enumerate(text.splitlines(), 1):
        stripped = line.strip()

        # Blank and comment lines are ignored and stop any continuation.
        if not stripped or stripped.startswith(("#", ";")):
            continuation = None
            continue

        # Indented text continues the preceding key (or continuation).
        if line[:1].isspace() and continuation is not None:
            section_name, key_name = continuation
            sections[section_name][key_name] += "\n" + stripped
            continue

        continuation = None

        if stripped.startswith("["):
            if len(stripped) < 2 or not stripped.endswith("]"):
                raise ParseError(lineno, "invalid section header")
            name = stripped[1:-1].strip()
            if name not in sections:
                sections[name] = {}
            current_section = name
            continue

        equals = stripped.find("=")
        colon = stripped.find(":")
        if equals == -1 and colon == -1:
            raise ParseError(
                lineno, "expected a section header or a key/value pair"
            )
        if equals == -1:
            split_at = colon
        elif colon == -1:
            split_at = equals
        else:
            split_at = min(equals, colon)

        key = stripped[:split_at].strip().lower()
        if not key:
            raise ParseError(lineno, "empty key")
        if current_section is None:
            raise ParseError(lineno, "key outside of a section")

        sections[current_section][key] = stripped[split_at + 1:].strip()
        continuation = (current_section, key)

    return _interpolate_all(sections)

